/// A comment's text, to the newline that ends it, which is left. The line
/// is not counted here, but by `skip`, which meets the newline.
pub fn skip_line(mut cs: Chars, mut pos: i64) -> kayak_rt::data::DataAt<'static, Here> {
    loop {
        if null_p(cs) {
            return here(cs, 0i64, pos);
        } else if char_eq_p(car(cs), '\n') {
            return here(cs, 0i64, pos);
        } else {
            (cs, pos) = (cdr(cs), i64_plus(pos, 1i64));
            continue;
        }
    }
}

/// Skips whitespace and comments, counting lines and characters; a `here`
/// made only where they end (C363).
pub fn skip_at(mut cs: Chars, mut line: i64, mut pos: i64) -> kayak_rt::data::DataAt<'static, Here> {
    loop {
        if null_p(cs) {
            return here(cs, line, pos);
        } else if char_eq_p(car(cs), '\n') {
            (cs, line, pos) = (cdr(cs), i64_plus(line, 1i64), i64_plus(pos, 1i64));
            continue;
        } else if char_whitespace_p(car(cs)) {
            (cs, pos) = (cdr(cs), i64_plus(pos, 1i64));
            continue;
        } else if char_eq_p(car(cs), ';') {
            let tagcase_ = skip_line(cdr(cs), i64_plus(pos, 1i64));
            if Here::__is_Here(tagcase_) {
                let (rest, zero, after,) = Here::__Here(tagcase_);
                (cs, pos) = (rest, after);
                continue;
            } else { kayak_rt::data::no_variant() }
        } else {
            return here(cs, line, pos);
        }
    }
}

#[inline]
pub fn skip(h: kayak_rt::data::DataAt<'static, Here>) -> kayak_rt::data::DataAt<'static, Here> {
    let tagcase_ = h;
    if Here::__is_Here(tagcase_) {
        let (cs, line, pos,) = Here::__Here(tagcase_);
        skip_at(cs, line, pos)
    } else { kayak_rt::data::no_variant() }
}

#[inline]
pub fn delimiter_p(c: char) -> bool {
    (char_whitespace_p(c) || char_eq_p(c, '(') || char_eq_p(c, ')') || char_eq_p(c, '"') || char_eq_p(c, ';'))
}

/// A token, `n` characters of it already read, from offset `from` of
/// `text`, whose rest is `cs`: its text, a `substring` of `text` (C363),
/// and `n`, how many.
pub fn token_at(mut cs: Chars, mut text: Str, mut from: i64, mut n: i64) -> kayak_rt::data::DataAt<'static, Tok> {
    loop {
        if (null_p(cs) || delimiter_p(car(cs))) {
            return tok(substring(text, i64_to_int(from), i64_to_int(i64_plus(from, n))), cs, n);
        } else {
            (cs, n) = (cdr(cs), i64_plus(n, 1i64));
            continue;
        }
    }
}

#[inline]
pub fn unescape(c: char) -> char {
    match c {
        'n' => {
            '\n'
        }
        't' => {
            '\t'
        }
        'r' => {
            i64_to_char(13i64)
        }
        _ => {
            c
        }
    }
}

/// R7RS's hex escape in a string (a backslash, `x41;`), after its `x`: the hex digits' value `n`,
/// `k` of them read, up to the `;`; the rest, as a token's text, the
/// character it names.
pub fn hex_escape(mut cs: Chars, mut n: i64, mut k: i64) -> kayak_rt::data::DataAt<'static, Tok> {
    loop {
        if null_p(cs) {
            return tok(str_lit!(""), cs, k);
        } else if i64_eq(char_to_i64(car(cs)), 59i64) {
            return tok(char_to_string(i64_to_char(n)), cdr(cs), i64_plus(k, 1i64));
        } else {
            let c = car(cs);
            let d = char_to_i64(c);
            (cs, n, k) = (cdr(cs), i64_plus(i64_star(n, 16i64), if (i64_gt_eq(d, 48i64) && i64_lt_eq(d, 57i64)) {
                i64_minus(d, 48i64)
            } else if (i64_gt_eq(d, 97i64) && i64_lt_eq(d, 102i64)) {
                i64_minus(d, 87i64)
            } else if (i64_gt_eq(d, 65i64) && i64_lt_eq(d, 70i64)) {
                i64_minus(d, 55i64)
            } else {
                0i64
            }), i64_plus(k, 1i64));
            continue;
        }
    }
}

/// A string's characters, after its opening quote on line `start`, at
/// offset `at`: its runs between escapes, `substring`s of `text` (C363),
/// newest first, the one now from `from`.
pub fn string_body(mut cs: Chars, mut text: Str, mut runs: Strings, mut from: i64, mut file: Str, mut start: i64, mut at: i64, mut line: i64, mut pos: i64) -> kayak_rt::data::DataAt<'static, Got> {
    loop {
        if null_p(cs) {
            return match read_error(file, start, str_lit!("a string is not closed")) {};
        } else if char_eq_p(car(cs), '"') {
            return got(str(string_list_append(reverse(kayak_rt::heap_cons(substring(text, i64_to_int(from), i64_to_int(pos)), runs))), file, at), here(cdr(cs), line, i64_plus(pos, 1i64)));
        } else if (char_eq_p(car(cs), '\\') && not(null_p(cdr(cs))) && i64_eq(char_to_i64(car(cdr(cs))), 120i64)) {
            let tagcase_ = hex_escape(cdr(cdr(cs)), 0i64, 0i64);
            if Tok::__is_Tok(tagcase_) {
                let (t, rest, k,) = Tok::__Tok(tagcase_);
                if string_eq_p(t, str_lit!("")) {
                    return match read_error(file, start, str_lit!("a string's hex escape is not closed by ;")) {};
                } else {
                    (cs, runs, from, pos) = (rest, kayak_rt::heap_cons(t, kayak_rt::heap_cons(substring(text, i64_to_int(from), i64_to_int(pos)), runs)), i64_plus(pos, i64_plus(k, 2i64)), i64_plus(pos, i64_plus(k, 2i64)));
                    continue;
                }
            } else { kayak_rt::data::no_variant() }
        } else if char_eq_p(car(cs), '\\') {
            (cs, runs, from, pos) = (cdr(cdr(cs)), kayak_rt::heap_cons(char_to_string(unescape(car(cdr(cs)))), kayak_rt::heap_cons(substring(text, i64_to_int(from), i64_to_int(pos)), runs)), i64_plus(pos, 2i64), i64_plus(pos, 2i64));
            continue;
        } else if char_eq_p(car(cs), '\n') {
            (cs, line, pos) = (cdr(cs), i64_plus(line, 1i64), i64_plus(pos, 1i64));
            continue;
        } else {
            (cs, pos) = (cdr(cs), i64_plus(pos, 1i64));
            continue;
        }
    }
}

/// Digits onto `n`, negated: so that -9223372036854775808, whose
/// magnitude is no i64, reads. A literal past an i64 is refused, as FX-26
/// refuses it where an i64 is expected.
pub fn digits_value(mut cs: Chars, mut n: i64, mut file: Str, mut line: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            let d = i64_minus(char_to_i64(car(cs)), 48i64);
            if (i64_lt(n, -922337203685477580i64) || (i64_eq(n, -922337203685477580i64) && i64_gt(d, 8i64))) {
                return match read_error(file, line, str_lit!("a literal past an i64")) {};
            } else {
                (cs, n) = (cdr(cs), i64_minus(i64_star(n, 10i64), d));
                continue;
            }
        }
    }
}

pub fn numeric_p(cs: Chars) -> bool {
    (not(null_p(cs)) && (char_numeric_p(car(cs)) || (char_eq_p(car(cs), '-') && not(null_p(cdr(cs))) && char_numeric_p(car(cdr(cs))))))
}

pub fn has_char_p(mut cs: Chars, mut c: char) -> bool {
    loop {
        if not(null_p(cs)) {
            if char_eq_p(car(cs), c) {
                return true;
            } else {
                cs = cdr(cs);
                continue;
            }
        } else {
            return false;
        }
    }
}

/// How many points `cs` has, or -1 if it has a character that is no
/// digit and no point.
pub fn point_count(mut cs: Chars, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else if char_eq_p(car(cs), '.') {
            (cs, n) = (cdr(cs), i64_plus(n, 1i64));
            continue;
        } else if char_numeric_p(car(cs)) {
            cs = cdr(cs);
            continue;
        } else {
            return -1i64;
        }
    }
}

/// Digits, after a `-` if any, with one point among them: a real, as FX-26
/// reads it (and Rust, written with a digit either side of the point).
#[inline]
pub fn real_token_p(cs: Chars) -> bool {
    i64_eq(point_count(if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    }, 0i64), 1i64)
}

pub fn digits_after_zeros(mut cs: Chars) -> Chars {
    loop {
        if (not(null_p(cs)) && not(null_p(cdr(cs))) && char_eq_p(car(cs), '0')) {
            cs = cdr(cs);
            continue;
        } else {
            return cs;
        }
    }
}

/// Whether digits `cs` are at most `most`, of as many digits.
pub fn digits_at_most_p(mut cs: Chars, mut most: Chars) -> bool {
    loop {
        if null_p(cs) {
            return true;
        } else if i64_lt(char_to_i64(car(cs)), char_to_i64(car(most))) {
            return true;
        } else if i64_gt(char_to_i64(car(cs)), char_to_i64(car(most))) {
            return false;
        } else {
            (cs, most) = (cdr(cs), cdr(most));
            continue;
        }
    }
}

/// Whether an integer literal is an i64's; one past is an `int`'s alone.
pub fn fits_i64_p(cs: Chars) -> bool {
    let negative = char_eq_p(car(cs), '-');
    let ds = digits_after_zeros(if negative {
        cdr(cs)
    } else {
        cs
    });
    let n = size(ds);
    if i64_lt(n, 19i64) {
        true
    } else if i64_gt(n, 19i64) {
        false
    } else {
        digits_at_most_p(ds, string_chars(if negative {
            str_lit!("9223372036854775808")
        } else {
            str_lit!("9223372036854775807")
        }))
    }
}

// Reals as FX-26 reads them past KFX's own (C155): its point first, `.5`,
// or an exponent, `1e-3`, as Rust's `f64` syntax has them. kfx's
// restriction pass refuses both, KFX writing a real as it is written.
pub fn all_digits_p(mut cs: Chars) -> bool {
    loop {
        if null_p(cs) {
            return true;
        } else {
            if char_numeric_p(car(cs)) {
                cs = cdr(cs);
                continue;
            } else {
                return false;
            }
        }
    }
}

pub fn point_first_real_p(cs: Chars) -> bool {
    let body = if (not(null_p(cs)) && char_eq_p(car(cs), '-')) {
        cdr(cs)
    } else {
        cs
    };
    (not(null_p(body)) && char_eq_p(car(body), '.') && not(null_p(cdr(body))) && all_digits_p(cdr(body)))
}

/// A real's mantissa, before its `e`.
pub fn before_exponent(cs: Chars) -> Chars {
    if (null_p(cs) || char_eq_p(car(cs), 'e') || char_eq_p(car(cs), 'E')) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), before_exponent(cdr(cs)))
    }
}

/// A real's exponent, after its `e`; none if it has none.
pub fn after_exponent(mut cs: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return nil::<char>();
        } else if (char_eq_p(car(cs), 'e') || char_eq_p(car(cs), 'E')) {
            return cdr(cs);
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

/// `[-]M e [+-]D`, `M` digits with at most one point among them, `D`
/// digits.
pub fn exponent_real_p(cs: Chars) -> bool {
    let body = if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    };
    let m = before_exponent(body);
    let x = after_exponent(body);
    let ds = if (not(null_p(x)) && (char_eq_p(car(x), '+') || char_eq_p(car(x), '-'))) {
        cdr(x)
    } else {
        x
    };
    (not(null_p(ds)) && all_digits_p(ds) && not(null_p(filter(kayak_rt::as_proc(kayak_rt::closure1s((), |(), c: char| {
        char_numeric_p(c)
    })), m))) && i64_lt_eq(point_count(m, 0i64), 1i64) && all_digits_p(filter(kayak_rt::as_proc(kayak_rt::closure1s((), |(), c: char| {
        not(char_eq_p(c, '.'))
    })), m)))
}

/// Whether a real is written as KFX writes one: neither its point first nor
/// with an exponent.
#[inline]
pub fn written_out_real_p(t: Str) -> bool {
    let cs = string_chars(t);
    not((point_first_real_p(cs) || has_char_p(cs, 'e') || has_char_p(cs, 'E')))
}

/// Whether every character of `cs` is one of `allowed`'s: `allowed`'s
/// characters made once, not again for each of `cs` (C476: a list of them
/// each, the reader's most of an edit build's character lists).
pub fn only_of_p(cs: Chars, allowed: Str) -> bool {
    let r#as = string_chars(allowed);
    not(any_p(kayak_rt::as_proc(kayak_rt::closure1s((r#as,), |(r#as,), c: char| {
        not(has_char_p(r#as, c))
    })), cs))
}

/// Hex digits onto `n`, as `digits-value`'s are, negated; one past an i64
/// refused (C116: Fixpt's arm64 encoder writes its instructions so).
pub fn hex_value(mut cs: Chars, mut n: i64, mut file: Str, mut line: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            let c = char_downcase(car(cs));
            let d = if char_numeric_p(c) {
                i64_minus(char_to_i64(c), 48i64)
            } else {
                i64_plus(10i64, i64_minus(char_to_i64(c), 97i64))
            };
            if i64_lt(n, -576460752303423487i64) {
                return match read_error(file, line, str_lit!("a hex literal past an i64, which KFX reads not yet")) {};
            } else {
                (cs, n) = (cdr(cs), i64_minus(i64_star(n, 16i64), d));
                continue;
            }
        }
    }
}

pub fn token_atom(s: Str, file: Str, line: i64, pos: i64) -> kayak_rt::data::DataAt<'static, Sexp> {
    let cs = string_chars(s);
    if (char_eq_p(car(cs), '#') && not(null_p(cdr(cs))) && (char_eq_p(car(cdr(cs)), 'x') || char_eq_p(car(cdr(cs)), 'X')) && not(null_p(cdr(cdr(cs))))) {
        // A hex literal, `#x1f`, `#x-1f`, R7RS's, as FX-26 reads it.
        let ds = cdr(cdr(cs));
        let negative = char_eq_p(car(ds), '-');
        let ds = if (negative || char_eq_p(car(ds), '+')) {
            cdr(ds)
        } else {
            ds
        };
        if (null_p(ds) || not(only_of_p(ds, str_lit!("0123456789abcdefABCDEF")))) {
            match read_error(file, line, string_append(str_lit!("no number KFX reads: "), s)) {}
        } else {
            let n = hex_value(ds, 0i64, file, line);
            if negative {
                num(n, file, pos)
            } else {
                if i64_eq(n, -9223372036854775808i64) {
                    match read_error(file, line, str_lit!("a hex literal past an i64, which KFX reads not yet")) {}
                } else {
                    num(i64_minus(0i64, n), file, pos)
                }
            }
        }
    } else if point_first_real_p(cs) {
        real(s, file, pos)
    } else if not(numeric_p(cs)) {
        sym(s, file, pos)
    } else if not(only_of_p(if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    }, str_lit!("0123456789.eE+-"))) {
        // Not a number, though a digit begins it (`1x`, `0x10`): a name, as
        // FX-26 reads it.
        sym(s, file, pos)
    } else if (has_char_p(cs, 'e') || has_char_p(cs, 'E')) {
        if exponent_real_p(cs) {
            real(s, file, pos)
        } else {
            match read_error(file, line, string_append(str_lit!("no number KFX reads: "), s)) {}
        }
    } else if has_char_p(cs, '.') {
        if (real_token_p(cs) && only_of_p(if char_eq_p(car(cs), '-') {
            cdr(cs)
        } else {
            cs
        }, str_lit!("0123456789."))) {
            real(s, file, pos)
        } else {
            match read_error(file, line, string_append(str_lit!("no number KFX reads: "), s)) {}
        }
    } else if not(only_of_p(if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    }, str_lit!("0123456789"))) {
        match read_error(file, line, string_append(str_lit!("no number KFX reads: "), s)) {}
    } else if not(fits_i64_p(cs)) {
        big(s, file, pos)
    } else if char_eq_p(car(cs), '-') {
        num(digits_value(cdr(cs), 0i64, file, line), file, pos)
    } else {
        num(i64_minus(0i64, digits_value(cs, 0i64, file, line)), file, pos)
    }
}

pub fn ascii_lowered(cs: Chars) -> Chars {
    if null_p(cs) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons({
            let k = char_to_i64(car(cs));
            if (i64_gt_eq(k, 65i64) && i64_lt_eq(k, 90i64)) {
                i64_to_char(i64_plus(k, 32i64))
            } else {
                car(cs)
            }
        }, ascii_lowered(cdr(cs)))
    }
}

/// The hexadecimal number `cs` writes, onto `n`; -1 if it writes none.
pub fn char_hex_value(mut cs: Chars, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            let k = char_to_i64(car(cs));
            let d = if (i64_gt_eq(k, 48i64) && i64_lt_eq(k, 57i64)) {
                i64_minus(k, 48i64)
            } else if (i64_gt_eq(k, 97i64) && i64_lt_eq(k, 102i64)) {
                i64_minus(k, 87i64)
            } else {
                the::<i64>(-1i64)
            };
            if (i64_lt(d, 0i64) || i64_gt(n, 1114111i64)) {
                return the::<i64>(-1i64);
            } else {
                (cs, n) = (cdr(cs), i64_plus(i64_star(n, 16i64), d));
                continue;
            }
        }
    }
}

/// A character's name after `#\`, as Fixpt's reader takes it
/// (`fixpt-read`'s `read_char`, C401): one character, itself; else a name,
/// its case aside, or `x` and its code in hexadecimal.
pub fn char_named(s: Str, file: Str, line: i64) -> char {
    if i64_eq(string_length_i64(s), 1i64) {
        string_ref_i64(s, 0i64)
    } else {
        let n = list_to_string(ascii_lowered(string_chars(s)));
        if string_eq_p(n, str_lit!("space")) {
            ' '
        } else if (string_eq_p(n, str_lit!("newline")) || string_eq_p(n, str_lit!("linefeed")) || string_eq_p(n, str_lit!("nl"))) {
            '\n'
        } else if string_eq_p(n, str_lit!("tab")) {
            '\t'
        } else if string_eq_p(n, str_lit!("return")) {
            i64_to_char(13i64)
        } else if (string_eq_p(n, str_lit!("null")) || string_eq_p(n, str_lit!("nul"))) {
            i64_to_char(0i64)
        } else if string_eq_p(n, str_lit!("alarm")) {
            i64_to_char(7i64)
        } else if string_eq_p(n, str_lit!("backspace")) {
            i64_to_char(8i64)
        } else if (string_eq_p(n, str_lit!("delete")) || string_eq_p(n, str_lit!("rubout"))) {
            i64_to_char(127i64)
        } else if (string_eq_p(n, str_lit!("escape")) || string_eq_p(n, str_lit!("altmode")) || string_eq_p(n, str_lit!("esc"))) {
            i64_to_char(27i64)
        } else if char_eq_p(string_ref_i64(n, 0i64), 'x') {
            let k = char_hex_value(cdr(string_chars(n)), 0i64);
            if (i64_lt(k, 0i64) || i64_gt(k, 1114111i64) || (i64_gt_eq(k, 55296i64) && i64_lt_eq(k, 57343i64))) {
                match read_error(file, line, string_append(str_lit!("bad character name `#\\"), string_append(s, str_lit!("`")))) {}
            } else {
                i64_to_char(k)
            }
        } else {
            match read_error(file, line, string_append(str_lit!("no character is named "), s)) {}
        }
    }
}

/// A datum at the start of `h`'s text, the rest of `text`, which `file`
/// holds.
pub fn read_datum(h: kayak_rt::data::DataAt<'static, Here>, text: Str, file: Str) -> kayak_rt::data::DataAt<'static, Got> {
    let tagcase_ = h;
    if Here::__is_Here(tagcase_) {
        let (cs, line, pos,) = Here::__Here(tagcase_);
        let c = car(cs);
        if char_eq_p(c, '(') {
            let tagcase_ = read_items(here(cdr(cs), line, i64_plus(pos, 1i64)), text, file);
            if Gots::__is_Gots(tagcase_) {
                let (xs, after,) = Gots::__Gots(tagcase_);
                got(lst(xs, file, line, pos), after)
            } else { kayak_rt::data::no_variant() }
        } else if char_eq_p(c, ')') {
            match read_error(file, line, str_lit!("a ) with no (")) {}
        } else if (i64_eq(char_to_i64(c), 39i64) && not(null_p(cdr(cs))) && not(string_eq_p(file, str_lit!("")))) {
            // `'d`, FX-26's `(quote d)` (C56), in a program's text; in the
            // checker's own (a file named ``), `'r` is a region binder's name.
            let tagcase_ = read_datum(skip_at(cdr(cs), line, i64_plus(pos, 1i64)), text, file);
            if Got::__is_Got(tagcase_) {
                let (x, after,) = Got::__Got(tagcase_);
                got(lst(kayak_rt::heap_cons(sym(str_lit!("quote"), file, pos), kayak_rt::heap_cons(x, kayak_rt::nil())), file, line, pos), after)
            } else { kayak_rt::data::no_variant() }
        } else if ((i64_eq(char_to_i64(c), 96i64) || i64_eq(char_to_i64(c), 44i64)) && not(null_p(cdr(cs))) && not(string_eq_p(file, str_lit!("")))) {
            // `` `d ``, `,d` and `,@d`: FX-26's `quasiquote`, `unquote` and
            // `unquote-splicing` (C79), in a program's text.
            let splice = (i64_eq(char_to_i64(c), 44i64) && char_eq_p(car(cdr(cs)), '@'));
            let rest = if splice {
                cdr(cdr(cs))
            } else {
                cdr(cs)
            };
            let head = if i64_eq(char_to_i64(c), 96i64) {
                str_lit!("quasiquote")
            } else if splice {
                str_lit!("unquote-splicing")
            } else {
                str_lit!("unquote")
            };
            let tagcase_ = read_datum(skip_at(rest, line, i64_plus(pos, if splice {
                2i64
            } else {
                1i64
            })), text, file);
            if Got::__is_Got(tagcase_) {
                let (x, after,) = Got::__Got(tagcase_);
                got(lst(kayak_rt::heap_cons(sym(head, file, pos), kayak_rt::heap_cons(x, kayak_rt::nil())), file, line, pos), after)
            } else { kayak_rt::data::no_variant() }
        } else if (char_eq_p(c, '#') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '(') && not(string_eq_p(file, str_lit!("")))) {
            // `#(d ...)`, a vector (C80): `(#vector d ...)`, a head no KFX name
            // is, which only a quote takes.
            let tagcase_ = read_items(here(cdr(cdr(cs)), line, i64_plus(pos, 2i64)), text, file);
            if Gots::__is_Gots(tagcase_) {
                let (xs, after,) = Gots::__Gots(tagcase_);
                got(lst(kayak_rt::heap_cons(sym(str_lit!("#vector"), file, pos), xs), file, line, pos), after)
            } else { kayak_rt::data::no_variant() }
        } else if char_eq_p(c, '"') {
            string_body(cdr(cs), text, nil::<Str>(), i64_plus(pos, 1i64), file, line, pos, line, i64_plus(pos, 1i64))
        } else if (char_eq_p(c, '#') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '\\')) {
            let name = cdr(cdr(cs));
            let tagcase_ = token_at(cdr(name), text, i64_plus(pos, 2i64), 1i64);
            if Tok::__is_Tok(tagcase_) {
                let (s, after, n,) = Tok::__Tok(tagcase_);
                got(chr(char_named(s, file, line), file, pos), here(after, line, i64_plus(pos, i64_plus(n, 2i64))))
            } else { kayak_rt::data::no_variant() }
        } else {
            let tagcase_ = token_at(cs, text, pos, 0i64);
            if Tok::__is_Tok(tagcase_) {
                let (s, after, n,) = Tok::__Tok(tagcase_);
                got(token_atom(s, file, line, pos), here(after, line, i64_plus(pos, n)))
            } else { kayak_rt::data::no_variant() }
        }
    } else { kayak_rt::data::no_variant() }
}

#[inline]
pub fn read_items(h: kayak_rt::data::DataAt<'static, Here>, text: Str, file: Str) -> kayak_rt::data::DataAt<'static, Gots> {
    read_items_onto(h, text, file, nil::<kayak_rt::data::DataAt<'static, Sexp>>())
}

/// A list's items, onto `acc` reversed, to its `)`: a loop (C524), not a
/// frame for each, each holding what it read (pinning a page as a
/// collection runs). `at`, not `h`, which a binding of it would hide.
pub fn read_items_onto(mut h: kayak_rt::data::DataAt<'static, Here>, mut text: Str, mut file: Str, mut acc: Sexps) -> kayak_rt::data::DataAt<'static, Gots> {
    loop {
        let at = skip(h);
        let tagcase_ = at;
        if Here::__is_Here(tagcase_) {
            let (cs, line, pos,) = Here::__Here(tagcase_);
            if null_p(cs) {
                return match read_error(file, line, str_lit!("a ( with no )")) {};
            } else if char_eq_p(car(cs), ')') {
                return gots(reverse(acc), here(cdr(cs), line, i64_plus(pos, 1i64)));
            } else {
                let tagcase_ = read_datum(at, text, file);
                if Got::__is_Got(tagcase_) {
                    let (x, after,) = Got::__Got(tagcase_);
                    (h, acc) = (after, kayak_rt::heap_cons(x, acc));
                    continue;
                } else { kayak_rt::data::no_variant() }
            }
        } else { kayak_rt::data::no_variant() }
    }
}

// Each datum from `h`, onto `acc` reversed, then in order: a loop (C524).
pub fn read_onto(mut h: kayak_rt::data::DataAt<'static, Here>, mut text: Str, mut file: Str, mut acc: Sexps) -> Sexps {
    loop {
        let at = skip(h);
        let tagcase_ = at;
        if Here::__is_Here(tagcase_) {
            let (cs, line, pos,) = Here::__Here(tagcase_);
            if null_p(cs) {
                return reverse(acc);
            } else {
                let tagcase_ = read_datum(at, text, file);
                if Got::__is_Got(tagcase_) {
                    let (x, after,) = Got::__Got(tagcase_);
                    (h, acc) = (after, kayak_rt::heap_cons(x, acc));
                    continue;
                } else { kayak_rt::data::no_variant() }
            }
        } else { kayak_rt::data::no_variant() }
    }
}

#[inline]
pub fn read_from(h: kayak_rt::data::DataAt<'static, Here>, text: Str, file: Str) -> Sexps {
    read_onto(h, text, file, nil::<kayak_rt::data::DataAt<'static, Sexp>>())
}

/// Every datum in `text`, of `file` from `line`.
#[inline]
pub fn read_all(text: Str, file: Str, line: i64) -> Sexps {
    read_from(here(string_chars(text), line, 0i64), text, file)
}

// Datum labels (C417), as Fixpt's reader has them for data
// (`fixpt-read`'s `datum_labels`) and its listings write them: `#N=` before
// a datum where it is first written, `#N#` for it after, so that what is
// written once is read once and shared. For data only (`read-data`): FX-26's
// program text has none (`fx26-grammar.md`), so `read-all` reads `#0=` as a
// name, which no program defines. Read as the reader reads any token, then
// resolved, in the order written.

// The labels made so far: an AVL tree by number.
#[derive(Clone, Copy)]
pub enum Labels {
    LbNone(),
    LbNode(kayak_rt::data::DataAt<'static, Labels>, i64, kayak_rt::data::DataAt<'static, Sexp>, i64, kayak_rt::data::DataAt<'static, Labels>),
}

